package genhelper

import (
	"bytes"
	"encoding/json/v2"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/ngicks/opiter"
)

// GeneratedComment returns the comment marking a file as generated by
// generator, in the form Go tools recognize:
//
//	// Code generated by generator. DO NOT EDIT.
//
// The comment must come before the package clause.
func GeneratedComment(generator string) string {
	return commentGroup(generatedCode(generator))
}

// GeneratorParams describes the run of a generator, for the header of the
// files it writes.
type GeneratorParams struct {
	// Name names the generator, usually by its import path.
	Name string
	// Argv holds the command line arguments of the run. It may be empty.
	//
	// The header repeats them, so arguments differing between machines,
	// such as absolute paths, make the generated file differ too.
	Argv []string
	// Params holds the settings of the run that are not arguments. The
	// values must encode with encoding/json/v2, which [GeneratorParams.Comment]
	// uses. It may be empty.
	Params map[string]any
	// Generated is the time of the run. It may be zero.
	//
	// The header repeats it, so every run makes the generated file differ.
	// [SameExceptGenerated] compares two files ignoring it.
	Generated time.Time
}

// GeneratedTimePrefix starts the line of the header holding
// [GeneratorParams.Generated].
const GeneratedTimePrefix = "// " + generatedLabel

// Comment returns the header section of g: the comment of
// [GeneratedComment], then the arguments, the parameters and the time of
// the run, as one comment group. [PrintFileHeader] and [WrapFile] take it
// as a section.
//
//	// Code generated by name. DO NOT EDIT.
//	// argv: -type T "an argument"
//	// params:
//	//	key: "value"
//	// generated: 2026-11-04T10:12:33Z
//
// The parameters are sorted by key and each value is printed as JSON by
// encoding/json/v2 with [json.Deterministic], which sorts the keys of
// nested maps too, so equal runs give equal text. The JSON leaves <, > and
// & unescaped. A nil slice or map prints as [] or {}, and an untyped nil
// prints as null. An argument or a key is quoted where it would not read
// as one word. The time is printed in UTC as RFC 3339, to the second. A
// line for empty Argv, empty Params or zero Generated is left out.
//
// Comment returns an error wrapping the [*json.SemanticError] of
// encoding/json/v2 for a value JSON does not encode, such as a channel,
// and an error wrapping a [*encoding/json/jsontext.SyntacticError] for a
// string holding invalid UTF-8.
func (g GeneratorParams) Comment() (string, error) {
	parts := []string{generatedCode(g.Name)}

	if len(g.Argv) > 0 {
		words := opiter.SlicesValues(g.Argv).
			Map(word).
			CollectSlice()

		parts = append(parts, "argv: "+strings.Join(words, " "))
	}

	if len(g.Params) > 0 {
		var params []string

		for key, param := range opiter.MapsSorted(g.Params) {
			value, err := json.Marshal(param, json.Deterministic(true))
			if err != nil {
				return "", fmt.Errorf("genhelper: generator parameter %q: %w", key, err)
			}

			params = append(params, word(key)+": "+string(value))
		}

		parts = append(parts, "params:", IndentComment(strings.Join(params, "\n")))
	}

	if !g.Generated.IsZero() {
		parts = append(parts, generatedLabel+g.Generated.UTC().Format(time.RFC3339))
	}

	return commentGroup(parts...), nil
}

// SameExceptGenerated reports whether a and b, two generated files, are
// equal once the line of their headers starting with [GeneratedTimePrefix]
// is ignored. A caller keeps the existing file of a run that would change
// only that line, so that regenerating without changes keeps the files byte
// for byte. Both must be formatted alike.
func SameExceptGenerated(a, b []byte) bool {
	return bytes.Equal(WithoutGenerated(a), WithoutGenerated(b))
}

// WithoutGenerated returns src, a generated file, without the line of its
// header starting with [GeneratedTimePrefix]. It returns src as it is when
// no such line precedes the package clause.
func WithoutGenerated(src []byte) []byte {
	rest := src
	for len(rest) > 0 {
		line, next, _ := bytes.Cut(rest, []byte("\n"))
		if bytes.HasPrefix(line, []byte("package ")) {
			break
		}

		if bytes.HasPrefix(line, []byte(GeneratedTimePrefix)) {
			start := len(src) - len(rest)
			return slices.Concat(src[:start], next)
		}

		rest = next
	}

	return src
}

// generatedLabel starts the text of the line holding
// [GeneratorParams.Generated], before [PrintCommentGroup] comments it.
const generatedLabel = "generated: "

// generatedCode returns the text of the line [GeneratedComment] prints.
func generatedCode(generator string) string {
	return "Code generated by " + generator + ". DO NOT EDIT."
}

// commentGroup returns parts printed by [PrintCommentGroup], without the
// final newline, so that the text reads as one section of
// [PrintFileHeader].
func commentGroup(parts ...string) string {
	p := NewPrinter(nil)
	PrintCommentGroup(p, parts)

	return strings.TrimSuffix(string(p.Bytes()), "\n")
}

// word returns s as it is when it reads as one word of a comment line, and
// quoted otherwise. Quoting keeps a line break of s from ending the
// comment.
func word(s string) string {
	quoted := strconv.Quote(s)
	if s == "" || quoted != `"`+s+`"` || strings.ContainsAny(s, " :") {
		return quoted
	}

	return s
}
